import json, sys

def truncate(s, n=300):
    s = s.replace("\n", " ⏎ ")
    return s if len(s) <= n else s[:n] + "...[TRUNC]"

def summarize(path):
    with open(path) as fh:
        for i, line in enumerate(fh):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception as e:
                print(f"[{i}] PARSE ERROR: {e}")
                continue
            ts = obj.get("timestamp", "")
            typ = obj.get("type", "")
            msg = obj.get("message", {})
            role = msg.get("role", "") if isinstance(msg, dict) else ""
            content = msg.get("content", None) if isinstance(msg, dict) else None
            attach = obj.get("attachment", None)
            line_out = f"[{i}] ts={ts} type={typ} role={role}"
            if attach:
                hn = attach.get("hookName") or attach.get("type")
                c = attach.get("content", "")
                line_out += f" ATTACH({hn}): {truncate(str(c), 200)}"
                print(line_out)
                continue
            if isinstance(content, str):
                line_out += f" TEXT: {truncate(content)}"
                print(line_out)
            elif isinstance(content, list):
                for block in content:
                    if not isinstance(block, dict):
                        continue
                    bt = block.get("type")
                    if bt == "text":
                        print(line_out + f" TEXT: {truncate(block.get('text',''))}")
                    elif bt == "tool_use":
                        print(line_out + f" TOOL_USE name={block.get('name')} input={truncate(json.dumps(block.get('input',{})), 300)}")
                    elif bt == "tool_result":
                        cont = block.get("content", "")
                        if isinstance(cont, list):
                            cont = " ".join(str(c.get("text","")) if isinstance(c, dict) else str(c) for c in cont)
                        print(line_out + f" TOOL_RESULT: {truncate(str(cont), 300)}")
                    else:
                        print(line_out + f" BLOCK({bt}): {truncate(json.dumps(block), 200)}")
            else:
                print(line_out + f" (no content) keys={list(obj.keys())}")

if __name__ == "__main__":
    summarize(sys.argv[1])

