43	// The tracker titled exactly `title`, or null if no issue carries it. Searches
44	// EVERY state: a tracker's resting state is closed, so a state-filtered lookup
45	// misses all of them.
46	//
47	// A tracker found OPEN is closed on the way back. Creation has closed since #951,
48	// but that only ever covered a tracker this code minted — one that predates the
49	// fix, or whose closing PATCH failed, had nothing anywhere that would ever look at
50	// its state again, so it sat open indefinitely (#904, open from 2026-08-16). The
51	// repair rides the lookup because every task's own run performs one, which is the
52	// only pass guaranteed to reach every tracker in the fleet.
53	export async function findTracker(gh, repo, title) {
54	  const want = title.trim();
55	  const q = encodeURIComponent(`repo:${repo} in:title "${want}"`);
56	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
57	  if (status !== 200 || !Array.isArray(json?.items)) {
58	    throw new Error(`could not search for the tracker ${JSON.stringify(want)}: search returned ${status}`);
59	  }
60	  const exact = json.items.filter((i) => (i.title ?? '').trim() === want);
61	  const found = pickTracker(exact, want);
62	  if (!found) return null;
63	  // Fail-soft, and deliberately so: an unclosable tracker is untidy, never a
64	  // reason to fail the run that was about to write its record.
65	  if (found.state === 'open') {
66	    await gh(`/repos/${repo}/issues/${found.number}`, {
67	      method: 'PATCH',
68	      body: { state: 'closed', state_reason: 'completed' },
69	    }).catch(() => {});
70	  }
71	  return { number: found.number, duplicates: exact.length - 1 };
72	}
